import{_ as e,o as t,c as i,ak as l}from"./chunks/framework.DKi5cyCJ.js";const p=JSON.parse('{"title":"GitLab 本地部署 · 05 管理与组织","description":"GitLab 管理侧最小可用配置：关闭公开注册、建 Group/Project、角色与保护分支约定。 在本地 GitLab 部署第 5 步、gitlab-local-05、组织权限初始化时使用。","frontmatter":{"name":"gitlab-local-05-admin","description":"GitLab 管理侧最小可用配置：关闭公开注册、建 Group/Project、角色与保护分支约定。 在本地 GitLab 部署第 5 步、gitlab-local-05、组织权限初始化时使用。"},"headers":[],"relativePath":"public/assets/attachments/gitlab-skills/gitlab-local-05-admin/SKILL.md","filePath":"public/assets/attachments/gitlab-skills/gitlab-local-05-admin/SKILL.md"}'),o={name:"public/assets/attachments/gitlab-skills/gitlab-local-05-admin/SKILL.md"};function r(d,a,n,s,c,h){return t(),i("div",null,[...a[0]||(a[0]=[l(`<h1 id="gitlab-本地部署-·-05-管理与组织" tabindex="-1">GitLab 本地部署 · 05 管理与组织 <a class="header-anchor" href="#gitlab-本地部署-·-05-管理与组织" aria-label="Permalink to &quot;GitLab 本地部署 · 05 管理与组织&quot;">​</a></h1><h2 id="前置" tabindex="-1">前置 <a class="header-anchor" href="#前置" aria-label="Permalink to &quot;前置&quot;">​</a></h2><ul><li>04 完成；管理员可登录 <code>$EXTERNAL_URL</code>。</li><li>变量：<code>DEFAULT_GROUP</code>（默认 <code>embedded</code>）、<code>DEFAULT_BRANCH</code>（默认 <code>main</code>）、<code>REPO_SIZE_LIMIT_MB</code>（可选）。</li></ul><h2 id="步骤-web-管理后台-路径因版本略有差异" tabindex="-1">步骤（Web 管理后台，路径因版本略有差异） <a class="header-anchor" href="#步骤-web-管理后台-路径因版本略有差异" aria-label="Permalink to &quot;步骤（Web 管理后台，路径因版本略有差异）&quot;">​</a></h2><h3 id="_1-关闭公开注册" tabindex="-1">1) 关闭公开注册 <a class="header-anchor" href="#_1-关闭公开注册" aria-label="Permalink to &quot;1) 关闭公开注册&quot;">​</a></h3><p>Admin → Settings → General → Sign-up restrictions：关闭 Sign-up enabled（或改为仅邀请）。</p><p>账号由管理员创建：Admin → Users。</p><h3 id="_2-建组织" tabindex="-1">2) 建组织 <a class="header-anchor" href="#_2-建组织" aria-label="Permalink to &quot;2) 建组织&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Group: $DEFAULT_GROUP</span></span>
<span class="line"><span>└── Project: &lt;按产品/模块命名，Private&gt;</span></span></code></pre></div><ul><li>一独立编译单元一仓；可见性 <strong>Private</strong>。</li><li>角色：Maintainer=模块负责人；Developer=日常开发；Reporter=只读。</li></ul><h3 id="_3-保护默认分支" tabindex="-1">3) 保护默认分支 <a class="header-anchor" href="#_3-保护默认分支" aria-label="Permalink to &quot;3) 保护默认分支&quot;">​</a></h3><p>Project → Settings → Repository → Protected branches：</p><table tabindex="0"><thead><tr><th>分支</th><th>建议</th></tr></thead><tbody><tr><td><code>$DEFAULT_BRANCH</code></td><td>禁止 force push；仅 Maintainer 合并</td></tr><tr><td><code>release/*</code></td><td>Protected</td></tr><tr><td><code>feature/*</code></td><td>不保护</td></tr></tbody></table><p>全组统一 <code>main</code> 或 <code>master</code>，名称一致优先。</p><h3 id="_4-可选-仓库大小" tabindex="-1">4) 可选：仓库大小 <a class="header-anchor" href="#_4-可选-仓库大小" aria-label="Permalink to &quot;4) 可选：仓库大小&quot;">​</a></h3><p>Admin → Settings → Repository：单仓上限约 <code>$REPO_SIZE_LIMIT_MB</code> MB（如 5120）。</p><h3 id="_5-本期明确不做" tabindex="-1">5) 本期明确不做 <a class="header-anchor" href="#_5-本期明确不做" aria-label="Permalink to &quot;5) 本期明确不做&quot;">​</a></h3><p>HTTPS、CI Runner、LDAP、SMTP——需要时另开任务，不阻塞本 Skill。</p><h2 id="完成门槛" tabindex="-1">完成门槛 <a class="header-anchor" href="#完成门槛" aria-label="Permalink to &quot;完成门槛&quot;">​</a></h2><ul><li>[ ] 公开注册已关</li><li>[ ] 至少 1 个 Group + 1 个 Private Project</li><li>[ ] 默认分支已保护</li><li>[ ] 角色约定已向用户确认（可先只建管理员自己的 Developer 测试账号）</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>→ <code>gitlab-local-06-client</code></p>`,22)])])}const u=e(o,[["render",r]]);export{p as __pageData,u as default};
